/// One ordinary operation over stable inode serials and checked names. Mode
/// values are permission bits only; access decisions belong to the mount's
/// default-permissions identity, not to this layer.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Operation {
    Create {
        parent: u64,
        name: PathName,
        mode: u32,
    },
    Mkdir {
        parent: u64,
        name: PathName,
        mode: u32,
    },
    Symlink {
        parent: u64,
        name: PathName,
        target: SymlinkTarget,
    },
    Link {
        serial: u64,
        parent: u64,
        name: PathName,
    },
    Unlink {
        parent: u64,
        name: PathName,
    },
    Rmdir {
        parent: u64,
        name: PathName,
    },
    /// `replace` false is the no-replace form. `destination_path` names the
    /// destination parent from the root; it is the ancestry evidence required
    /// when a directory moves to another parent, and is verified, not trusted.
    Rename {
        parent: u64,
        name: PathName,
        new_parent: u64,
        new_name: PathName,
        replace: bool,
        destination_path: Option<Vec<PathName>>,
    },
    /// chmod, utimens and/or truncate of one inode; absent fields are
    /// unchanged. A changed size sets the mtime unless one is given.
    SetAttributes {
        serial: u64,
        mode: Option<u32>,
        mtime: Option<Time>,
        size: Option<u64>,
    },
    /// One byte window of at most `WRITE_WINDOW`; larger writes arrive as
    /// several operations. There is no total size, edit or flow limit.
    /// Descriptor mutation revalidates exact open custody in every owner round.
    WriteOpen {
        file: OpenFile,
        position: Position,
        data: WriteData,
    },
    SetOpenAttributes {
        file: OpenFile,
        mode: Option<u32>,
        mtime: Option<Time>,
        size: Option<u64>,
    },
    /// A shared-mapping store reaching the daemon after the fact. Its bytes
    /// land at their own offset, clipped to the size current in the publishing
    /// job: a store never extends the file, and one wholly beyond the size
    /// changes nothing. Only a live descriptor of the inode is required.
    StoreOpen {
        file: OpenFile,
        offset: u64,
        data: WriteData,
    },
    Write {
        serial: u64,
        position: Position,
        data: WriteData,
    },
}
impl Operation {
    pub(crate) const fn file(&self) -> Option<OpenFile> {
        match self {
            Self::WriteOpen { file, .. }
            | Self::SetOpenAttributes { file, .. }
            | Self::StoreOpen { file, .. } => Some(*file),
            _ => None,
        }
    }
    /// Whether preparation needs one serial from the Workspace's allocator.
    pub const fn creates(&self) -> bool {
        matches!(
            self,
            Self::Create { .. } | Self::Mkdir { .. } | Self::Symlink { .. }
        )
    }
    pub fn destination_path(&self) -> Option<&[PathName]> {
        match self {
            Self::Rename {
                destination_path, ..
            } => destination_path.as_deref(),
            _ => None,
        }
    }
}
