    fn get_volume_info(&self, out_volume_info: &mut VolumeInfo) -> winfsp::Result<()> {
        let total = DECLARED_BLOCKS * BLOCK_BYTES;
        out_volume_info.total_size = total;
        out_volume_info.free_size = total;
