#[cfg(not(unix))]
pub fn init_observed(
    _storage: &Storage,
    _catalog: &dyn HistoryCatalog,
    _request: InitRequest<'_>,
    _timer: &TimingScope<'_, Active>,
    _counters: Arc<InitCounters>,
) -> ProjectResult<Initialized> {
    Err(ProjectError::Unsupported)
}

